      matchedAspect = 'anglais';
    } sinon if (normEg === normalizedQuery) {
      note += 95 ;
      matchedAspect = 'arabe-par exemple';
    } sinon si (normFusha === normalizedQuery) {
      note += 90 ;
      matchedAspect = 'arabe-fusha';
    }

    //La sous-chaîne contient
    if (normEn.includes(normalizedQuery)) {
      note += 50 ;
      matchedAspect = 'anglais';
    } sinon if (normEg.includes(normalizedQuery)) {
      note += 45 ;
      matchedAspect = 'arabe-par exemple';
    } sinon if (normFusha.includes(normalizedQuery)) {
      note += 40 ;
      matchedAspect = 'arabe-fusha';
    } sinon if (normGrammar.includes(normalizedQuery)) {
