/**
 * Phrase quotidienne déterministe (identique pour tous les utilisateurs un jour donné)
 */
fonction d'exportation asynchrone getDailySentence() : Promise<SentenceItem | nul> {
  const all = wait loadSentences();
  if (all. length === 0) renvoie null ;

  const aujourd'hui = new Date();
  const dayOfYear = Math.floor(
    (aujourd'hui.getTime() - nouvelle Date(aujourd'hui.getFullYear(), 0, 0).getTime()) / 1000/60/60/24
  );
  const index = Math.abs((dayOfYear * 97 + aujourd'hui.getFullYear()) % all.length);
  renvoyer tout[index] || tout[0];
}

/**
 * Phrase déterministe de la semaine
 */
fonction d'exportation asynchrone getSentenceOfTheWeek() : Promise<SentenceItem | nul> {
  const all = wait loadSentences();
  if (all. length === 0) renvoie null ;

  const aujourd'hui = new Date();
  const weekNumber = Math.ceil(
    ((aujourd'hui.getTime() - new Date(today.getFullYear(), 0, 1). getTime()) / 86400000 + 1) / 7
  );
  // Préférez B2 ou C1 pour la phrase de la semaine
  const b2c1 = all.filter(s => s.cefr === 'B2' || s.cefr === 'C1');
  const pool = b2c1.length > 0 ? b2c1 : tout ;
  const index = Math.abs((weekNumber * 31) % pool.length);
  pool de retour[index] || piscine[0] ;
}

